// Fleet Maintenance Scheduler: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const INT = { oil_change: [5000, 90, 35000], brake_pads: [20000, 365, 60000], tyre_rotation: [10000, 180, 15000], air_filter: [15000, 365, 12000] };
const today = new Date(); today.setHours(0, 0, 0, 0);
const out = [];
for (const v of input) {
  const items = [];
  for (const [item, [kmInt, dayInt, cost]] of Object.entries(INT)) {
    const byKm = (Number(v[item + '_km']) + kmInt - Number(v.odometer)) / Number(v.daily_km);
    const byTime = (new Date(v[item + '_date'] + 'T00:00:00').getTime() + dayInt * 864e5 - today) / 864e5;
    const left = Math.round(Math.min(byKm, byTime));
    if (left <= 14) items.push({ item: item.replace('_', ' '), left, cost, by: byKm <= byTime ? 'km' : 'time' });
  }
  if (items.length) out.push({ vehicle: v.id, overdue: items.some(i => i.left < 0), cost: items.reduce((s, i) => s + i.cost, 0),
    work_order: items.map(i => `${i.item}: ${i.left < 0 ? 'OVERDUE' : 'due in ' + i.left + 'd'} (by ${i.by})`).join('; ') });
}
out.sort((a, b) => b.overdue - a.overdue);
return out.map(json => ({ json }));
